# These programmes run 42 months but were catalogued with a whole-year length, so their plans
# stored that rounded number while every estimate already counted 42 months.
HALF_YEAR_COURSES = {"psu-phuket": 3, "malaya": 4}


def store_course_length(apps, schema_editor):
    StudyPlan = apps.get_model("finance", "StudyPlan")
    for key, rounded in HALF_YEAR_COURSES.items():
        StudyPlan.objects.filter(school_key=key, years=rounded).update(years=3.5)


